    expect(inspectStr(undefined)).to.equal('null');
  });

  it('correctly print various strings', () => {
    expect(inspectStr('')).to.equal('``');
    expect(inspectStr('a')).to.equal('`a`');
    expect(inspectStr('"')).to.equal('`"`');
