import { expect } from 'chai';
import { describe, it } from 'mocha';

import { suggestionList } from '../suggestionList';

function expectSuggestions(input: string, options: ReadonlyArray<string>) {
  return expect(suggestionList(input, options));
}

describe('suggestionList', () => {
  it('Returns results when input is empty', () => {
    expectSuggestions('', ['a']).to.deep.equal(['a']);
  });

  it('Returns empty array when there are no options', () => {
    expectSuggestions('input', []).to.deep.equal([]);
  });

  it('Returns options with small lexical distance', () => {
    expectSuggestions('greenish', ['green']).to.deep.equal(['green']);
    expectSuggestions('green', ['greenish']).to.deep.equal(['greenish']);
  });

  it('Rejects options with distance that exceeds threshold', () => {
    // spell-checker:disable
    expectSuggestions('aaaa', ['aaab']).to.deep.equal(['aaab']);
    expectSuggestions('aaaa', ['aabb']).to.deep.equal(['aabb']);
    expectSuggestions('aaaa', ['abbb']).to.deep.equal([]);
    // spell-checker:enable

    expectSuggestions('ab', ['ca']).to.deep.equal([]);
  });

  it('Returns options with different case', () => {
    // cSpell:ignore verylongstring
    expectSuggestions('verylongstring', ['VERYLONGSTRING']).to.deep.equal([
      'VERYLONGSTRING',
    ]);

    expectSuggestions('VERYLONGSTRING', ['verylongstring']).to.deep.equal([
      'verylongstring',
    ]);

    expectSuggestions('VERYLONGSTRING', ['VeryLongString']).to.deep.equal([
      'VeryLongString',
    ]);
  });

  it('Returns options with transpositions', () => {
    expectSuggestions('agr', ['arg']).to.deep.equal(['arg']);
    expectSuggestions('214365879', ['123456789']).to.deep.equal(['123456789']);
  });

  it('Returns options sorted based on lexical distance', () => {
    expectSuggestions('abc', ['a', 'ab', 'abc']).to.deep.equal([
      'abc',
      'ab',
      'a',
    ]);
  });

  it('Returns options with the same lexical distance sorted lexicographically', () => {
    expectSuggestions('a', ['az', 'ax', 'ay']).to.deep.equal([
      'ax',
      'ay',
      'az',
    ]);
  });
});

import { expect } from 'chai';
import { describe, it } from 'mocha';

import type { ObjMapLike } from '../ObjMap';
import { toObjMap } from '../toObjMap';

// Workaround to make both ESLint happy
const __proto__ = '__proto__';

describe('toObjMap', () => {
  it('convert undefined to ObjMap', () => {
    const result = toObjMap(undefined);
    expect(result).to.deep.equal({});
    expect(Object.getPrototypeOf(result)).to.equal(null);
  });

  it('convert null to ObjMap', () => {
    const result = toObjMap(null);
    expect(result).to.deep.equal({});
    expect(Object.getPrototypeOf(result)).to.equal(null);
  });

  it('convert empty object to ObjMap', () => {
    const result = toObjMap({});
    expect(result).to.deep.equal({});
    expect(Object.getPrototypeOf(result)).to.equal(null);
  });

  it('convert object with own properties to ObjMap', () => {
    const obj: ObjMapLike<string> = Object.freeze({ foo: 'bar' });

    const result = toObjMap(obj);
    expect(result).to.deep.equal(obj);
    expect(Object.getPrototypeOf(result)).to.equal(null);
  });

  it('convert object with __proto__ property to ObjMap', () => {
    const protoObj = Object.freeze({ toString: false });
    const obj = Object.create(null);
    obj[__proto__] = protoObj;
    Object.freeze(obj);

    const result = toObjMap(obj);
    expect(Object.keys(result)).to.deep.equal(['__proto__']);
    expect(Object.getPrototypeOf(result)).to.equal(null);
    expect(result[__proto__]).to.equal(protoObj);
  });

  it('passthrough empty ObjMap', () => {
    const objMap = Object.create(null);
    expect(toObjMap(objMap)).to.deep.equal(objMap);
  });

  it('passthrough ObjMap with properties', () => {
    const objMap = Object.freeze({
      __proto__: null,
      foo: 'bar',
    });
    expect(toObjMap(objMap)).to.deep.equal(objMap);
  });
});

import { expect } from 'chai';
import { describe, it } from 'mocha';

import {
  dedentBlockStringLines,
  isPrintableAsBlockString,
  printBlockString,
} from '../blockString';

function joinLines(...args: ReadonlyArray<string>) {
  return args.join('\n');
}

describe('dedentBlockStringLines', () => {
  function expectDedent(lines: ReadonlyArray<string>) {
    return expect(dedentBlockStringLines(lines));
  }

  it('handles empty string', () => {
    expectDedent(['']).to.deep.equal([]);
  });

  it('does not dedent first line', () => {
    expectDedent(['  a']).to.deep.equal(['  a']);
    expectDedent([' a', '  b']).to.deep.equal([' a', 'b']);
  });

  it('removes minimal indentation length', () => {
    expectDedent(['', ' a', '  b']).to.deep.equal(['a', ' b']);
    expectDedent(['', '  a', ' b']).to.deep.equal([' a', 'b']);
    expectDedent(['', '  a', ' b', 'c']).to.deep.equal(['  a', ' b', 'c']);
  });

  it('dedent both tab and space as single character', () => {
    expectDedent(['', '\ta', '          b']).to.deep.equal(['a', '         b']);
    expectDedent(['', '\t a', '          b']).to.deep.equal(['a', '        b']);
    expectDedent(['', ' \t a', '          b']).to.deep.equal(['a', '       b']);
  });

  it('dedent do not take empty lines into account', () => {
    expectDedent(['a', '', ' b']).to.deep.equal(['a', '', 'b']);
    expectDedent(['a', ' ', '  b']).to.deep.equal(['a', '', 'b']);
  });

  it('removes uniform indentation from a string', () => {
    const lines = [
      '',
      '    Hello,',
      '      World!',
      '',
      '    Yours,',
      '      GraphQL.',
    ];
    expectDedent(lines).to.deep.equal([
      'Hello,',
      '  World!',
      '',
      'Yours,',
      '  GraphQL.',
    ]);
  });

  it('removes empty leading and trailing lines', () => {
    const lines = [
      '',
      '',
      '    Hello,',
      '      World!',
      '',
      '    Yours,',
      '      GraphQL.',
      '',
      '',
    ];
    expectDedent(lines).to.deep.equal([
      'Hello,',
      '  World!',
      '',
      'Yours,',
      '  GraphQL.',
    ]);
  });

  it('removes blank leading and trailing lines', () => {
    const lines = [
      '  ',
      '        ',
      '    Hello,',
      '      World!',
      '',
      '    Yours,',
      '      GraphQL.',
      '        ',
      '  ',
    ];
    expectDedent(lines).to.deep.equal([
      'Hello,',
      '  World!',
      '',
      'Yours,',
      '  GraphQL.',
    ]);
  });

  it('retains indentation from first line', () => {
    const lines = [
      '    Hello,',
      '      World!',
      '',
      '    Yours,',
      '      GraphQL.',
    ];
    expectDedent(lines).to.deep.equal([
      '    Hello,',
      '  World!',
      '',
      'Yours,',
      '  GraphQL.',
    ]);
  });

  it('does not alter trailing spaces', () => {
    const lines = [
      '               ',
      '    Hello,     ',
      '      World!   ',
      '               ',
      '    Yours,     ',
      '      GraphQL. ',
      '               ',
    ];
    expectDedent(lines).to.deep.equal([
      'Hello,     ',
      '  World!   ',
      '           ',
      'Yours,     ',
      '  GraphQL. ',
    ]);
  });
});

describe('isPrintableAsBlockString', () => {
  function expectPrintable(str: string) {
    return expect(isPrintableAsBlockString(str)).to.equal(true);
  }

  function expectNonPrintable(str: string) {
    return expect(isPrintableAsBlockString(str)).to.equal(false);
  }

  it('accepts valid strings', () => {
    expectPrintable('');
    expectPrintable(' a');
    expectPrintable('\t"\n"');
    expectNonPrintable('\t"\n \n\t"');
  });

  it('rejects strings with only whitespace', () => {
    expectNonPrintable(' ');
    expectNonPrintable('\t');
    expectNonPrintable('\t ');
    expectNonPrintable(' \t');
  });

  it('rejects strings with non-printable characters', () => {
    expectNonPrintable('\x00');
    expectNonPrintable('a\x00b');
  });

  it('rejects strings with only empty lines', () => {
    expectNonPrintable('\n');
    expectNonPrintable('\n\n');
    expectNonPrintable('\n\n\n');
    expectNonPrintable(' \n  \n');
    expectNonPrintable('\t\n\t\t\n');
  });

  it('rejects strings with carriage return', () => {
    expectNonPrintable('\r');
    expectNonPrintable('\n\r');
    expectNonPrintable('\r\n');
    expectNonPrintable('a\rb');
  });

  it('rejects strings with leading empty lines', () => {
    expectNonPrintable('\na');
    expectNonPrintable(' \na');
    expectNonPrintable('\t\na');
    expectNonPrintable('\n\na');
  });

  it('rejects strings with trailing empty lines', () => {
    expectNonPrintable('a\n');
    expectNonPrintable('a\n ');
    expectNonPrintable('a\n\t');
    expectNonPrintable('a\n\n');
  });
});

describe('printBlockString', () => {
  function expectBlockString(str: string) {
    return {
      toEqual(expected: string | { readable: string; minimize: string }) {
        const { readable, minimize } =
          typeof expected === 'string'
            ? { readable: expected, minimize: expected }
            : expected;

        expect(printBlockString(str)).to.equal(readable);
        expect(printBlockString(str, { minimize: true })).to.equal(minimize);
      },
    };
  }

  it('does not escape characters', () => {
    const str = '" \\ / \b \f \n \r \t';
    expectBlockString(str).toEqual({
      readable: '"""\n' + str + '\n"""',
      minimize: '"""\n' + str + '"""',
    });
  });

  it('by default print block strings as single line', () => {
    const str = 'one liner';
    expectBlockString(str).toEqual('"""one liner"""');
  });

  it('by default print block strings ending with triple quotation as multi-line', () => {
    const str = 'triple quotation """';
    expectBlockString(str).toEqual({
      readable: '"""\ntriple quotation \\"""\n"""',
      minimize: '"""triple quotation \\""""""',
    });
  });

  it('correctly prints single-line with leading space', () => {
    const str = '    space-led string';
    expectBlockString(str).toEqual('"""    space-led string"""');
  });

  it('correctly prints single-line with leading space and trailing quotation', () => {
    const str = '    space-led value "quoted string"';
    expectBlockString(str).toEqual(
      '"""    space-led value "quoted string"\n"""',
    );
  });

  it('correctly prints single-line with trailing backslash', () => {
    const str = 'backslash \\';
    expectBlockString(str).toEqual({
      readable: '"""\nbackslash \\\n"""',
      minimize: '"""backslash \\\n"""',
    });
  });

  it('correctly prints multi-line with internal indent', () => {
    const str = 'no indent\n with indent';
    expectBlockString(str).toEqual({
      readable: '"""\nno indent\n with indent\n"""',
      minimize: '"""\nno indent\n with indent"""',
    });
  });

  it('correctly prints string with a first line indentation', () => {
    const str = joinLines(
      '    first  ',
      '  line     ',
      'indentation',
      '     string',
    );

    expectBlockString(str).toEqual({
      readable: joinLines(
        '"""',
        '    first  ',
        '  line     ',
        'indentation',
        '     string',
        '"""',
      ),
      minimize: joinLines(
        '"""    first  ',
        '  line     ',
        'indentation',
        '     string"""',
      ),
    });
  });
});

import { expect } from 'chai';
import { describe, it } from 'mocha';

import { dedent } from '../../__testUtils__/dedent';
import { expectToThrowJSON } from '../../__testUtils__/expectJSON';

import { inspect } from '../../jsutils/inspect';

import { GraphQLError } from '../../error/GraphQLError';

import type { Token } from '../ast';
import { isPunctuatorTokenKind, Lexer } from '../lexer';
import { Source } from '../source';
import { TokenKind } from '../tokenKind';

function lexOne(str: string) {
  const lexer = new Lexer(new Source(str));
  return lexer.advance();
}

function lexSecond(str: string) {
  const lexer = new Lexer(new Source(str));
  lexer.advance();
  return lexer.advance();
}

function expectSyntaxError(text: string) {
  return expectToThrowJSON(() => lexSecond(text));
}

describe('Lexer', () => {
  it('ignores BOM header', () => {
    expect(lexOne('\uFEFF foo')).to.contain({
      kind: TokenKind.NAME,
      start: 2,
      end: 5,
      value: 'foo',
    });
  });

  it('tracks line breaks', () => {
    expect(lexOne('foo')).to.contain({
      kind: TokenKind.NAME,
      start: 0,
      end: 3,
      line: 1,
      column: 1,
      value: 'foo',
    });
    expect(lexOne('\nfoo')).to.contain({
      kind: TokenKind.NAME,
      start: 1,
      end: 4,
      line: 2,
      column: 1,
      value: 'foo',
    });
    expect(lexOne('\rfoo')).to.contain({
      kind: TokenKind.NAME,
      start: 1,
      end: 4,
      line: 2,
      column: 1,
      value: 'foo',
    });
    expect(lexOne('\r\nfoo')).to.contain({
      kind: TokenKind.NAME,
      start: 2,
      end: 5,
      line: 2,
      column: 1,
      value: 'foo',
    });
    expect(lexOne('\n\rfoo')).to.contain({
      kind: TokenKind.NAME,
      start: 2,
      end: 5,
      line: 3,
      column: 1,
      value: 'foo',
    });
    expect(lexOne('\r\r\n\nfoo')).to.contain({
      kind: TokenKind.NAME,
      start: 4,
      end: 7,
      line: 4,
      column: 1,
      value: 'foo',
    });
    expect(lexOne('\n\n\r\rfoo')).to.contain({
      kind: TokenKind.NAME,
      start: 4,
      end: 7,
      line: 5,
      column: 1,
      value: 'foo',
    });
  });

  it('records line and column', () => {
    expect(lexOne('\n \r\n \r  foo\n')).to.contain({
      kind: TokenKind.NAME,
      start: 8,
      end: 11,
      line: 4,
      column: 3,
      value: 'foo',
    });
  });

  it('can be Object.toStringified, JSON.stringified, or jsutils.inspected', () => {
    const lexer = new Lexer(new Source('foo'));
    const token = lexer.advance();

    expect(Object.prototype.toString.call(lexer)).to.equal('[object Lexer]');

    expect(Object.prototype.toString.call(token)).to.equal('[object Token]');
    expect(JSON.stringify(token)).to.equal(
      '{"kind":"Name","value":"foo","line":1,"column":1}',
    );
    expect(inspect(token)).to.equal(
      '{ kind: "Name", value: "foo", line: 1, column: 1 }',
    );
  });

  it('skips whitespace and comments', () => {
    expect(
      lexOne(`

    foo


`),
    ).to.contain({
      kind: TokenKind.NAME,
      start: 6,
      end: 9,
      value: 'foo',
    });

    expect(lexOne('\t\tfoo\t\t')).to.contain({
      kind: TokenKind.NAME,
      start: 2,
      end: 5,
      value: 'foo',
    });

    expect(
      lexOne(`
    #comment
    foo#comment
`),
    ).to.contain({
      kind: TokenKind.NAME,
      start: 18,
      end: 21,
      value: 'foo',
    });

    expect(lexOne(',,,foo,,,')).to.contain({
      kind: TokenKind.NAME,
      start: 3,
      end: 6,
      value: 'foo',
    });
  });

  it('errors respect whitespace', () => {
    let caughtError;
    try {
      lexOne(['', '', ' ~', ''].join('\n'));
    } catch (error) {
      caughtError = error;
    }
    expect(String(caughtError)).to.equal(dedent`
      Syntax Error: Unexpected character: "~".

      GraphQL request:3:2
      2 |
      3 |  ~
        |  ^
      4 |
    `);
  });

  it('updates line numbers in error for file context', () => {
    let caughtError;
    try {
      const str = ['', '', '     ~', ''].join('\n');
      const source = new Source(str, 'foo.js', { line: 11, column: 12 });
      new Lexer(source).advance();
    } catch (error) {
      caughtError = error;
    }
    expect(String(caughtError)).to.equal(dedent`
      Syntax Error: Unexpected character: "~".

      foo.js:13:6
      12 |
      13 |      ~
         |      ^
      14 |
    `);
  });

  it('updates column numbers in error for file context', () => {
    let caughtError;
    try {
      const source = new Source('~', 'foo.js', { line: 1, column: 5 });
      new Lexer(source).advance();
    } catch (error) {
      caughtError = error;
    }
    expect(String(caughtError)).to.equal(dedent`
      Syntax Error: Unexpected character: "~".

      foo.js:1:5
      1 |     ~
        |     ^
    `);
  });

  it('lexes strings', () => {
    expect(lexOne('""')).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 2,
      value: '',
    });

    expect(lexOne('"simple"')).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 8,
      value: 'simple',
    });

    expect(lexOne('" white space "')).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 15,
      value: ' white space ',
    });

    expect(lexOne('"quote \\""')).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 10,
      value: 'quote "',
    });

    expect(lexOne('"escaped \\n\\r\\b\\t\\f"')).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 20,
      value: 'escaped \n\r\b\t\f',
    });

    expect(lexOne('"slashes \\\\ \\/"')).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 15,
      value: 'slashes \\ /',
    });

    expect(lexOne('"unescaped unicode outside BMP \u{1f600}"')).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 34,
      value: 'unescaped unicode outside BMP \u{1f600}',
    });

    expect(
      lexOne('"unescaped maximal unicode outside BMP \u{10ffff}"'),
    ).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 42,
      value: 'unescaped maximal unicode outside BMP \u{10ffff}',
    });

    expect(lexOne('"unicode \\u1234\\u5678\\u90AB\\uCDEF"')).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 34,
      value: 'unicode \u1234\u5678\u90AB\uCDEF',
    });

    expect(lexOne('"unicode \\u{1234}\\u{5678}\\u{90AB}\\u{CDEF}"')).to.contain(
      {
        kind: TokenKind.STRING,
        start: 0,
        end: 42,
        value: 'unicode \u1234\u5678\u90AB\uCDEF',
      },
    );

    expect(
      lexOne('"string with unicode escape outside BMP \\u{1F600}"'),
    ).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 50,
      value: 'string with unicode escape outside BMP \u{1f600}',
    });

    expect(lexOne('"string with minimal unicode escape \\u{0}"')).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 42,
      value: 'string with minimal unicode escape \u{0}',
    });

    expect(
      lexOne('"string with maximal unicode escape \\u{10FFFF}"'),
    ).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 47,
      value: 'string with maximal unicode escape \u{10FFFF}',
    });

    expect(
      lexOne('"string with maximal minimal unicode escape \\u{00000000}"'),
    ).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 57,
      value: 'string with maximal minimal unicode escape \u{0}',
    });

    expect(
      lexOne('"string with unicode surrogate pair escape \\uD83D\\uDE00"'),
    ).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 56,
      value: 'string with unicode surrogate pair escape \u{1f600}',
    });

    expect(
      lexOne('"string with minimal surrogate pair escape \\uD800\\uDC00"'),
    ).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 56,
      value: 'string with minimal surrogate pair escape \u{10000}',
    });

    expect(
      lexOne('"string with maximal surrogate pair escape \\uDBFF\\uDFFF"'),
    ).to.contain({
      kind: TokenKind.STRING,
      start: 0,
      end: 56,
      value: 'string with maximal surrogate pair escape \u{10FFFF}',
    });
  });

  it('lex reports useful string errors', () => {
    expectSyntaxError('"').to.deep.equal({
      message: 'Syntax Error: Unterminated string.',
      locations: [{ line: 1, column: 2 }],
    });

    expectSyntaxError('"""').to.deep.equal({
      message: 'Syntax Error: Unterminated string.',
      locations: [{ line: 1, column: 4 }],
    });

    expectSyntaxError('""""').to.deep.equal({
      message: 'Syntax Error: Unterminated string.',
      locations: [{ line: 1, column: 5 }],
    });

    expectSyntaxError('"no end quote').to.deep.equal({
      message: 'Syntax Error: Unterminated string.',
      locations: [{ line: 1, column: 14 }],
    });

